module BasedeTiempo2(
input wire clk,
input wire rst_in,
output reg rst_out
);
//-------------------------------------------------
//-----------------Signals-------------------------
reg [3:0] N_S;
reg [3:0] P_S;  //-----------------Process-------------------------
  always @(P_S) begin
    if((P_S == 29'b11101110011010110010100000000)) begin
      //if(P_S = "0011") then
      N_S <= {4{1'b0}};
      rst_out <= 1'b1;
    end
    else begin
      N_S <= P_S + 1'b1;
      rst_out <= 1'b0;
    end
  end
  always @(posedge clk, posedge rst_in, posedge rst_in) begin
    if((rst_in == 1'b1)) begin
      P_S <= {4{1'b0}};
