module ALU_Mux(
input wire [3:0] OP,
input wire [7:0] ARITH,
input wire [7:0] LOGIC,
input wire [7:0] SHIFT,
input wire [7:0] MEMORY,
input wire [3:0] CCR_ARITH,
input wire [3:0] CCR_LOGIC,
output reg [7:0] ALU_OUT,
output reg [3:0] CCR_OUT
);
  always @(*) begin
    case(OP)
      4'b0000 : ALU_OUT <= ARITH;
  // ADD
      4'b0001 : ALU_OUT <= ARITH;
  // SUB
      4'b0010 : ALU_OUT <= LOGIC;
  // AND
      4'b0011 : ALU_OUT <= LOGIC;
  // OR
      4'b0100 : ALU_OUT <= LOGIC;
  // CMP
      4'b0101 : ALU_OUT <= ARITH;
  // ADDI
      4'b0110 : ALU_OUT <= LOGIC;
  // ANDI
      4'b0111 : ALU_OUT <= SHIFT;
  // SL
      4'b1000 : ALU_OUT <= SHIFT;
  // SR
      4'b1001 : ALU_OUT <= MEMORY;
  // LW
      default : ALU_OUT <= MEMORY;
    endcase
  end
  // SW
  always @(*) begin
    case(OP)
      4'b0000 : CCR_OUT <= CCR_ARITH;
  // ADD
      4'b0001 : CCR_OUT <= CCR_ARITH;
  // SUB
      4'b0010 : CCR_OUT <= CCR_LOGIC;
  // AND
      4'b0011 : CCR_OUT <= CCR_LOGIC;
  // OR
      4'b0100 : CCR_OUT <= CCR_LOGIC;
  // CMP
      4'b0101 : CCR_OUT <= CCR_ARITH;
  // ADDI
      4'b0110 : CCR_OUT <= CCR_LOGIC;
  // ANDI
      default : CCR_OUT <= 4'b0000;
    endcase
  end
    // All flags cleared for other LOGIC operations
endmodule

