module conv_24to8(
input wire clk_in,
input wire reset_in,
input wire [23:0] data24_in,
input wire valid24_in,
output reg ready24_out,
output reg [7:0] data8_out,
output reg valid8_out,
input wire ready8_in
);
// System clock & reset
// 24-bit data coming in
// 8-bit data going out
parameter [1:0]
  S_WRITE_MSB = 0,
  S_WRITE_MID = 1,
  S_WRITE_LSB = 2;
reg [1:0] state = S_WRITE_MSB;
reg [1:0] state_next;
reg [7:0] lsb = 1'b0;
reg [7:0] lsb_next;
reg [7:0] mid = 1'b0;
reg [7:0] mid_next;
  // Infer registers
  always @(posedge clk_in) begin
    if((reset_in == 1'b1)) begin
      state <= S_WRITE_MSB;
      lsb <= {8{1'b0}};
      mid <= {8{1'b0}};
    end
    else begin
      state <= state_next;
      lsb <= lsb_next;
      mid <= mid_next;
    end
  end
  // Next state logic
  always @(state, lsb, mid, data24_in, valid24_in, ready8_in) begin
    state_next <= state;
    valid8_out <= 1'b0;
    lsb_next <= lsb;
    mid_next <= mid;
    case(state)
        // Write the LSB and return to MSB:
    S_WRITE_LSB : begin
      ready24_out <= 1'b0;
      // not ready for data from 24-bit side
      data8_out <= lsb;
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE_MSB;
      end
      // Write the mid byte and move on to LSB
    end
    S_WRITE_MID : begin
      ready24_out <= 1'b0;
      // not ready for data from 24-bit side
      data8_out <= mid;
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE_LSB;
      end
      // When a word arrives, write the MSB and move on to mid byte:				
    end
    default : begin
      ready24_out <= ready8_in;
      // ready for data from 24-bit side
      data8_out <= data24_in[23:16];
      valid8_out <= valid24_in;
      if((valid24_in == 1'b1 && ready8_in == 1'b1)) begin
        mid_next <= data24_in[15:8];
        lsb_next <= data24_in[7:0];
        state_next <= S_WRITE_MID;
      end
    end
    endcase
  end
endmodule

