module edgeDetector(
input wire clk,
input wire reset,
input wire enable,
input wire input,
output reg detected
);
  always @(posedge clk, posedge reset) begin : P1
    reg currentState;
    reg previousState;
      // Reset
    if(reset == 1'b1) begin
      currentState = 1'b0;
      previousState = 1'b0;
      detected <= 1'b0;
      // Synchronous behaviour
    end else begin
      if(enable == 1'b1) begin
        // Update states
        previousState = currentState;
        currentState = input;
        // If the current state is high, and the previous state was low,
        // an edge has arrived:
        detected <= currentState &  ~previousState;
      end
    end
  end
endmodule

