module UART_RX_CTRL(
input wire UART_RX,
input wire CLK,
output reg [7:0] DATA,
output reg READ_DATA,
input wire RESET_READ
);
parameter FREQ = 100000000;  // 100MHz Nexys4 CLK
parameter BAUD = 9600;
reg [31:0] count = 0;
parameter sample_0 = 3 * FREQ / (BAUD * 2) - 1;
parameter sample_1 = 5 * FREQ / (BAUD * 2) - 1;
parameter sample_2 = 7 * FREQ / (BAUD * 2) - 1;
parameter sample_3 = 9 * FREQ / (BAUD * 2) - 1;
parameter sample_4 = 11 * FREQ / (BAUD * 2) - 1;
parameter sample_5 = 13 * FREQ / (BAUD * 2) - 1;
parameter sample_6 = 15 * FREQ / (BAUD * 2) - 1;
parameter sample_7 = 17 * FREQ / (BAUD * 2) - 1;
parameter stop_bit = 19 * FREQ / (BAUD * 2) - 1;
reg [7:0] byte = 1'b0;
  always @(posedge CLK) begin
    if((RESET_READ == 1'b1)) begin
      READ_DATA <= 1'b0;
    end
    case(count)
    sample_0 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_1 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_2 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_3 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_4 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_5 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_6 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    sample_7 : begin
      byte <= {UART_RX,byte[7:1]};
    end
    stop_bit : begin
      if(UART_RX == 1'b1) begin
        DATA <= byte;
        READ_DATA <= 1'b1;
      end
    end
    default : begin
    end
    endcase
    if(count == stop_bit) begin
      count <= 0;
    end
    else if(count == 0) begin
      if(UART_RX == 1'b0) begin
        count <= count + 1;
      end
    end
    else begin
      count <= count + 1;
    end
  end
endmodule

