// Sample clock at 3125000Hz.
reg [16 + clkDiv:0] counter;
  always @(posedge clk, posedge period, posedge enable) begin
    if((counter[(16 + clkDiv):clkDiv] < {1'b0,period}) && (enable == 1'b1)) begin
      counter <= (counter) + 1;
    end
    else begin
      counter <= {((16 + clkDiv)-(0)+1){1'b0}};
    end
