//---------------------------------------------------------------------
// IPIC Reset Input 
//---------------------------------------------------------------------
//---------------------------------------------------------------------
// Combined Reset Output 
//---------------------------------------------------------------------
// Signals
wire sig_axi_reset = 1'b0;
wire sig_ipic_reset = 1'b0;
reg sig_combined_reset = 1'b0;
  //(architecture implementation)
  // Assign the output port
  assign rst2ip_reset_out = sig_combined_reset;
  // Generate an active high combined reset from the 
  // axi reset input and the IPIC reset input
  assign sig_axi_reset =  ~(axi_aresetn);
  assign sig_ipic_reset = ip2bus_mst_reset;
  //-----------------------------------------------------------
  // Synchronous Process with Sync Reset
  //
  // Label: IMP_RST_REG
  //
  // Process Description:
  //   Implements the register for the combined reset output.
  //
  //-----------------------------------------------------------
  always @(posedge axi_aclk) begin
    if((sig_axi_reset == 1'b1)) begin
      sig_combined_reset <= 1'b1;
    end
    else begin
      sig_combined_reset <= sig_axi_reset | sig_ipic_reset;
    end
