reg [31:0] sample_counter;
  Timer #(
      .CLOCK_FREQUENCY(CLOCK_FREQUENCY),
    .TIMER_FREQUENCY(SAMPLE_FREQUENCY))
  sample_clock(
      .clock(clock),
    .reset(reset),
    .tick(sample_tick));
  always @(posedge clock) begin
    if(reset == 1'b1) begin
      sync <= {2{1'b0}};
      sample_counter <= 0;
      d_out <= 1'b0;
    end
    else begin
      sync <= {sync[0],d_in};
      if(sync[1] == 1'b0) begin
        sample_counter <= 0;
        d_out <= 1'b0;
      end
      else if(sample_tick == 1'b1) begin
        if(sample_counter == SAMPLE_COUNT) begin
          d_out <= 1'b1;
        end
        else begin
          sample_counter <= sample_counter + 1;
        end
      end
    end
  end
endmodule

