module WB(
input wire clock,
input wire reset,
input wire [31:0] data_from_MEM,
input wire [5:0] cntl_from_ID,
output wire [31:0] rfile_write_data_to_ID,
output wire [4:0] rfile_write_addr_to_ID,
output wire rfile_write_e_to_ID
);
//These two outputs also used for
//forwarding logic
////Component Declarations\\--
//Generic rising-edge-triggered register
//\\Component Declarations//--
////Signal Declarations\\--
//These signals are used between the three registers that make up the three-stage
//buffer that delays the incoming control signals from the instruction decoder
wire [5:0] buffer_1_2;
wire [5:0] buffer_2_3;
wire [5:0] buffer_out;  //\\Signal Declarations//--
  //The input register for the stage
  GenReg #(
      .size(32))
  in_reg(
      .clock(clock),
    .enable(1'b1),
    .reset(reset),
    .data(data_from_MEM),
    .output(rfile_write_data_to_ID));
  //The buffer's registers
  GenReg #(
      .size(6))
  buf1(
      .clock(clock),
    .enable(1'b1),
    .reset(reset),
    .data(cntl_from_ID),
    .output(buffer_1_2));
  GenReg #(
      .size(6))
  buf2(
      .clock(clock),
    .enable(1'b1),
    .reset(reset),
    .data(buffer_1_2),
    .output(buffer_2_3));
  GenReg #(
      .size(6))
  buf3(
      .clock(clock),
    .enable(1'b1),
    .reset(reset),
    .data(buffer_2_3),
    .output(buffer_out));
  //These signals, the write address and write enable for the register
  //file, go straight to the ID stage. The data to be written is simply
  //the output of the input register
  assign rfile_write_addr_to_ID = buffer_out[5:1];
  assign rfile_write_e_to_ID = buffer_out[0];
endmodule

module ServoControl(
input wire [7:0] Angulo,
input wire Clk,
input wire Rst,
output wire Senal
);
//Embedded Signal needed by Frequency divider
//Frequency divider counter declaration
parameter MaxCta = 2000000;  //definir valor de acuerda a la tableta
reg [31:0] ContDiv;  //Embedded Signal neede for DivDisp
wire [31:0] PulsoNecesario;
  assign PulsoNecesario = 100000 + (Angulo) * 392;
  //Frequency divider section
  always @(posedge Rst, posedge Clk) begin
      //Asinchronous Reset
    if((Rst == 1'b1)) begin
      ContDiv <= 0;
    end else begin
      //Check if counter has reached the final count
      if((ContDiv == MaxCta)) begin
        ContDiv <= 0;
      end
      else begin
        //no ha transcurrido un segundo, seguir incrementando el contador
        ContDiv <= ContDiv + 1;
      end
    end
  end
