reg [7:0] data_buffer;
reg buffer_valid;

// Combinational circuit
assign and_out = in & {100{select}};
assign or_out = in | {100{select}};
assign xor_out = in ^ {100{select}};
assign comb_out = (select) ? (and_out[7:0] + or_out[7:0] + xor_out[7:0]) : (and_out[7:0] & or_out[7:0] & xor_out[7:0]);

// Pipeline stage 1
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        buffer_valid <= 1'b0;
    end else if (valid_a && ready_b) begin
        buffer_valid <= 1'b1;
        data_buffer <= comb_out;
    end else begin
        buffer_valid <= 1'b0;
    end
end

// Pipeline accumulator
reg [3:0] counter;
reg [9:0] accumulator;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        valid_b <= 1'b0;
        accumulator <= 10'b0;
        counter <= 4'b0;
    end else if (buffer_valid && ready_b) begin
        if (counter == 4'b1111) begin
            valid_b <= 1'b1;
            accumulator <= accumulator + data_buffer;
            counter <= 4'b0;
        end else begin
            valid_b <= 1'b0;
            accumulator <= accumulator + data_buffer;
            counter <= counter + 1'b1;
        end
    end else begin
        valid_b <= 1'b0;
    end
end

// Output assignment
assign ready_a = ready_b;
assign data_out = accumulator;

endmodule

