module decoder(
input wire [7:0] instruction_in,
output reg s_exec_nop,
output reg s_exec_sta,
output reg s_exec_lda,
output reg s_exec_add,
output reg s_exec_or,
output reg s_exec_shr,
output reg s_exec_shl,
output reg s_exec_mul,
output reg s_exec_and,
output reg s_exec_not,
output reg s_exec_jmp,
output reg s_exec_jn,
output reg s_exec_jz,
output reg s_exec_hlt
);
//decod_instr : out  STD_LOGIC_VECTOR(3 downto 0);
  // decod_instr	<= instruction_in(7 downto 4);
  // 0000 -> NOP
  // 0001 -> STA
  // 0010 -> LDA
  // 0011 -> ADD
  // 0100 -> OR
  // 0101 -> AND
  // 0110 -> NOT
  // 0111 -> SHR
  // 1000 -> JMP
  // 1001 -> JN
  // 1010 -> JZ
  // 1011 -> SHL
  // 1100 -> MUL
  // 1111 -> HLT
  always @(instruction_in[7:4]) begin
    // Set all as zero
    s_exec_nop <= 1'b0;
    s_exec_sta <= 1'b0;
    s_exec_lda <= 1'b0;
    s_exec_add <= 1'b0;
    s_exec_or <= 1'b0;
    s_exec_and <= 1'b0;
    s_exec_not <= 1'b0;
    s_exec_jmp <= 1'b0;
    s_exec_jn <= 1'b0;
    s_exec_jz <= 1'b0;
    s_exec_hlt <= 1'b0;
    s_exec_shr <= 1'b0;
    s_exec_shl <= 1'b0;
    s_exec_mul <= 1'b0;
    if((instruction_in[7:4] == 4'b0000)) begin
      // NOP
      s_exec_nop <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b0001)) begin
      // STA
      s_exec_sta <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b0010)) begin
      // LDA
      s_exec_lda <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b0011)) begin
      // ADD
      s_exec_add <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b0100)) begin
      // OR
      s_exec_or <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b0101)) begin
      // AND
      s_exec_and <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b0110)) begin
      // NOT
      s_exec_not <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b1000)) begin
      // JMP
      s_exec_jmp <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b1001)) begin
      // JN
      s_exec_jn <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b1010)) begin
      // JZ
      s_exec_jz <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b1111)) begin
      // HLT
      s_exec_hlt <= 1'b1;
      // Challenge instructions SHR, SHL e MUL
    end
    else if((instruction_in[7:4] == 4'b0111)) begin
      // SHR
      s_exec_shr <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b1011)) begin
      // SHL
      s_exec_shl <= 1'b1;
    end
    else if((instruction_in[7:4] == 4'b1100)) begin
      // MUL
      s_exec_mul <= 1'b1;
      // End challenge
    end
  end
endmodule

module grain(
input wire CLK_I,
input wire CLKEN_I,
input wire ARESET_I,
input wire KEY_I,
input wire IV_I,
input wire INIT_I,
output wire KEYSTREAM_O,
output wire KEYSTREAM_VALID_O
);
parameter DEBUG=false;
parameter FAST=false;
// attempt manual register balancing
parameter [1:0]
  IDLE = 0,
  INIT_KEYIV = 1,
  INIT_RUN = 2;
reg [1:0] state;
reg [7:0] cnt = 1'b0;
reg cnt79 = 1'b0; reg cnt63 = 1'b0; reg cnt239 = 1'b0;
reg inject_input; reg set_injected_iv; reg allow_output;
reg add_output;
wire output_bit; reg output_bit_d; reg allow_output_d;
  assign KEYSTREAM_O = output_bit_d;
  assign KEYSTREAM_VALID_O = allow_output_d;
  generate if (FAST == false) begin: slow_design
      grain_datapath_slow #(
          .DEBUG(DEBUG))
    functions0(
          .CLK_I(CLK_I),
      .CLKEN_I(CLKEN_I),
      .ARESET_I(ARESET_I),
      .KEY_I(KEY_I),
      .IV_I(IV_I),
      .INJECT_INPUT_I(inject_input),
      .PAD_IV_I(set_injected_iv),
      .ADD_OUTPUT_I(add_output),
      .H_O(output_bit));
  end
  endgenerate
  generate if (FAST == true) begin: fast_design
      grain_datapath_fast #(
          .DEBUG(DEBUG))
    functions1(
          .CLK_I(CLK_I),
      .CLKEN_I(CLKEN_I),
      .ARESET_I(ARESET_I),
      .KEY_I(KEY_I),
      .IV_I(IV_I),
      .INJECT_INPUT_I(inject_input),
      .PAD_IV_I(set_injected_iv),
      .ADD_OUTPUT_I(add_output),
      .H_O(output_bit));
  end
  endgenerate
  // output registers:
  // (in case the "user" forgets this is at 
  //  his end and kills my fmax)
  // 
  always @(posedge CLK_I, posedge ARESET_I) begin
    if(ARESET_I == 1'b1) begin
      output_bit_d <= 1'b0;
      allow_output_d <= 1'b0;
    end else begin
      if(CLKEN_I == 1'b1) begin
        output_bit_d <= output_bit;
        allow_output_d <= allow_output;
      end
    end
  end
  // the counter:
  always @(posedge CLK_I) begin
    if(CLKEN_I == 1'b1) begin
      if(state == IDLE) begin
        cnt <= 9'b0000_0001;
      end
      else begin
        cnt <= cnt + 1;
      end
      if(cnt == 79) begin
        cnt79 <= 1'b1;
      end
      else begin
        cnt79 <= 1'b0;
      end
      if(cnt == 63) begin
        cnt63 <= 1'b1;
      end
      else begin
        cnt63 <= 1'b0;
      end
      if(cnt == 239) begin
        cnt239 <= 1'b1;
      end
      else begin
        cnt239 <= 1'b0;
      end
    end
  end
  // the controller fsm:
  always @(posedge CLK_I, posedge ARESET_I) begin
    if(ARESET_I == 1'b1) begin
      state <= IDLE;
      inject_input <= 1'b0;
      set_injected_iv <= 1'b0;
      add_output <= 1'b0;
      allow_output <= 1'b0;
    end else begin
      if(CLKEN_I == 1'b1) begin
        case(state)
        IDLE : begin
          if(INIT_I == 1'b1) begin
            state <= INIT_KEYIV;
            inject_input <= 1'b1;
            set_injected_iv <= 1'b0;
            allow_output <= 1'b0;
          end
        end
        INIT_KEYIV : begin
          if(cnt63 == 1'b1) begin
            set_injected_iv <= 1'b1;
          end
          if(cnt79 == 1'b1) begin
            state <= INIT_RUN;
            inject_input <= 1'b0;
            add_output <= 1'b1;
          end
        end
        INIT_RUN : begin
          if(cnt239 == 1'b1) begin
            state <= IDLE;
            add_output <= 1'b0;
            allow_output <= 1'b1;
          end
        end
        default : begin
          state <= IDLE;
        end
        endcase
      end
    end
  end
endmodule

