module arith_unit(
input wire [15:0] RA,
input wire [15:0] RB,
input wire [2:0] OP,
output wire [15:0] AR_OUT,
output wire [3:0] SREG_OUT
);
wire [16:0] a = 1'b0; wire [16:0] b = 1'b0;
reg [16:0] RESULT = 1'b0;
wire [3:0] SREG = 1'b0;
  assign a = {1'b0,RA};
  assign b = {1'b0,RB};
  always @(*) begin
    case(OP)
      3'b000,3'b101 : RESULT <= (a) + (b);
  // ADD
      3'b001 : RESULT <= (a) - (b);
  // SUB
  //a + b when "101",	-- ADDI
      default : RESULT <= {1'b0,16'h0000};
    endcase
  end
  assign SREG[3] = RESULT[15];
  // Negative with signed logic
  assign SREG[2] = RESULT[15:0] == 32'h00000000 ? 1'b1 : 1'b0;
  // Zero
  assign SREG[1] = RESULT[16] ^ RESULT[15];
  // Overflow with signed logic
  assign SREG[0] = RESULT[16];
  // Carry
  assign SREG_OUT = SREG;
  assign AR_OUT = RESULT[15:0];
endmodule

