module pc_controller(
input wire [2:0] opcode,
output reg stack_push,
output reg [1:0] pc_value_select,
output reg inc_select,
output reg stack_clk_enable
);
// opcode input
// stack push/pop signal
// pc update value select
// increment select
// stack clock enable
// this circuit requires no internal signals
  always @(opcode) begin
    // opcode 000 is increment pc by 4
    if(opcode == 3'b000) begin
      stack_push <= 1'b0;
      pc_value_select <= 2'b00;
      inc_select <= 1'b0;
      stack_clk_enable <= 1'b0;
      // opcode 001 is set pc to value
    end
    else if(opcode == 3'b001) begin
      stack_push <= 1'b0;
      pc_value_select <= 2'b01;
      inc_select <= 1'b0;
      stack_clk_enable <= 1'b0;
      // opcode 010 is increment pc by value
    end
    else if(opcode == 3'b010) begin
      stack_push <= 1'b0;
      pc_value_select <= 2'b00;
      inc_select <= 1'b1;
      stack_clk_enable <= 1'b0;
      // opcode 100 is push to stack and set pc
    end
    else if(opcode == 3'b100) begin
      stack_push <= 1'b1;
      pc_value_select <= 2'b01;
      inc_select <= 1'b0;
      stack_clk_enable <= 1'b1;
      // opcode 101 is push to stack and increment pc by value
    end
    else if(opcode == 3'b101) begin
      stack_push <= 1'b1;
      pc_value_select <= 2'b00;
      inc_select <= 1'b1;
      stack_clk_enable <= 1'b1;
      // opcode 110 is pop from stack
    end
    else if(opcode == 3'b110) begin
      stack_push <= 1'b0;
      pc_value_select <= 2'b10;
      inc_select <= 1'b0;
      stack_clk_enable <= 1'b1;
      // otherwise invalid opcode, all outputs 0
    end
    else begin
      stack_push <= 1'b0;
      pc_value_select <= 2'b00;
      inc_select <= 1'b0;
      stack_clk_enable <= 1'b0;
    end
  end
endmodule

