  generate if (internal_rom == 3) begin: gen_internal_os_b
      // d800 to dfff (2k)
    os2 rom2(
          .clock(clock),
      .address(rom_addr[10:0]),
      .q(ROM2_data));
    // e000 to ffff (8k)
    os8 rom10(
          .clock(clock),
      .address(rom_addr[12:0]),
      .q(ROM8_data));
    always @(rom_addr) begin
      case(rom_addr[13:11])
      3'b011 : begin
        ROM_DATA <= ROM2_data;
      end
      3'b100,3'b101,3'b110,3'b111 : begin
        ROM_DATA <= ROM8_data;
      end
      default : begin
        ROM_DATA <= 8'hff;
      end
      endcase
    end
    assign rom_request_complete = rom_request_reg;
  end
  endgenerate
  generate if (internal_rom == 2) begin: gen_internal_os_loop
      os16_loop rom16a(
          .clock(clock),
      .address(rom_addr[13:0]),
      .q(ROM16_data));
    assign ROM_DATA = ROM16_DATA;
    assign rom_request_complete = rom_request_reg;
  end
  endgenerate
  generate if (internal_rom == 1) begin: gen_internal_os
      os16 rom16a(
          .clock(clock),
      .address(rom_addr[13:0]),
      .q(ROM16_data));
    basic basic1(
          .clock(clock),
      .address(rom_addr[12:0]),
      .q(BASIC_data));
    always @(rom16_data, basic_data, rom_addr[15:0]) begin
      ROM_DATA <= ROM16_DATA;
      if((rom_addr[15] == 1'b1)) begin
        ROM_DATA <= BASIC_DATA;
      end
    end
    assign rom_request_complete = rom_request_reg;
  end
  endgenerate
  generate if (internal_rom == 0) begin: gen_no_internal_os
      assign ROM16_data = {1{1'b0}};
    assign rom_request_complete = 1'b0;
  end
  endgenerate
  generate if (internal_ram > 0) begin: gen_internal_ram
      generic_ram_infer #(
          .ADDRESS_WIDTH(19),
      .SPACE(internal_ram),
      .DATA_WIDTH(8))
    ramint1(
          .clock(clock),
      .address(ram_addr),
      .data(ram_data_in[7:0]),
      .we(RAM_WR_ENABLE),
      .q(ram_data));
    assign ram_request_complete = ram_request_reg;
  end
  endgenerate
  generate if (internal_ram == 0) begin: gen_no_internal_ram
      assign ram_request_complete = 1'b1;
    assign ram_data = {1{1'b1}};
  end
  endgenerate
endmodule

module d_flip_flop_sync_reset (
    input clk,
    input reset,
    input d,
    output reg q
);

    always @(posedge clk) begin
        if (reset)
            q <= 0;
        else
            q <= d;
    end

endmodule

